-- Modelos de anamnese prontos (2026-10-18): Avaliação Multidisciplinar, Anamnese Avaliação TEA/TGD e
-- Atualização de Rotina e Acompanhamento Terapêutico. Entram em config/anamnesis_types (modelos da EMPRESA) e são
-- editáveis como qualquer modelo (Prontuário ▾ → Anamneses → Outras Opções ▾ → Modelos). Só acrescenta os que ainda
-- não existem (pelo id); nunca altera um modelo que você já editou. Pode rodar de novo.
-- Já aplicada em produção pelo conector em 2026-10-18 (conferida: 154 / 322 / 64 perguntas).
insert into public.documents (path, unit_id, data)
values ('config/anamnesis_types', 'empresa', '{"list":[]}'::jsonb)
on conflict (path, unit_id) do nothing;

