update public.documents set data = jsonb_set(data, '{list}', coalesce(data -> 'list', '[]'::jsonb) || jsonb_build_array($j${"id":"anam-acompanhamento","name":"Atualização de Rotina e Acompanhamento Terapêutico","descricao":"Formulário curto para atualizar rotina, medicação, escola, terapias, plano de saúde e expectativas da família no acompanhamento.","validadeMeses":3,"versao":1,"perguntas":[{"id":"ac001","tipo":"bloco","titulo":"Atualização de rotina e acompanhamento terapêutico. Este formulário atualiza informações importantes sobre a rotina, o desenvolvimento, as terapias e as necessidades atuais da criança. O preenchimento auxilia a equipe no acompanhamento e no planejamento terapêutico."},{"id":"ac002","tipo":"secao","titulo":"1. Identificação"},{"id":"ac003","tipo":"texto","titulo":"Nome da criança","obrigatoria":true,"campo":"nome"},{"id":"ac004","tipo":"texto","titulo":"Responsável","obrigatoria":true},{"id":"ac005","tipo":"secao","titulo":"2. Medicação"},{"id":"ac006","tipo":"simnao","titulo":"Faz uso de medicação?","obrigatoria":true},{"id":"ac007","tipo":"texto","titulo":"Qual medicação?","campo":"medicacoes","cond":{"q":"ac006","op":"igual","v":"sim"}},{"id":"ac008","tipo":"simnao","titulo":"Houve suspensão ou mudança de medicação recentemente?"},{"id":"ac009","tipo":"texto","titulo":"Qual mudança?","cond":{"q":"ac008","op":"igual","v":"sim"}},{"id":"ac010","tipo":"secao","titulo":"3. Mudanças de Rotina"},{"id":"ac011","tipo":"simnao","titulo":"Houve mudanças de rotina?","obrigatoria":true},{"id":"ac012","tipo":"multipla","titulo":"Quais mudanças?","opcoes":[{"id":"o1","label":"Horários"},{"id":"o2","label":"Sono"},{"id":"o3","label":"Alimentação"},{"id":"o4","label":"Residência"},{"id":"o5","label":"Escola"},{"id":"o6","label":"Atividades"},{"id":"o7","label":"Terapias"},{"id":"o8","label":"Cuidadores"},{"id":"o9","label":"Professores"},{"id":"o10","label":"Pessoas na família"}],"cond":{"q":"ac011","op":"igual","v":"sim"}},{"id":"ac013","tipo":"textolo