 where path = 'config/anamnesis_types' and unit_id = 'empresa'
   and not exists (select 1 from jsonb_array_elements(coalesce(data -> 'list', '[]'::jsonb)) e where e ->> 'id' = 'anam-acompanhamento');

-- Conferência: 3 modelos prontos
select count(*) as modelos_prontos from public.documents d, jsonb_array_elements(d.data -> 'list') e
 where d.path = 'config/anamnesis_types' and e ->> 'id' in ('anam-multidisciplinar', 'anam-tea-tgd', 'anam-acompanhamento');
